      /*  Quick capture API  */
      openQuickCapture(prefill) {
        new CadenceCaptureModal(this.app, {
          plugin: this,
          defaultText: prefill && prefill.text ? prefill.text : "",
          defaultStart: prefill && prefill.start ? prefill.start : null,
          defaultWhen: prefill && prefill.when ? prefill.when : null,
          defaultRepeat: prefill && prefill.repeat ? prefill.repeat : "none",
          defaultRepeatInterval: prefill && prefill.repeatInterval ? prefill.repeatInterval : 1,
          defaultRepeatDays: prefill && prefill.repeatDays ? prefill.repeatDays : [],
          defaultRepeatWeeks: prefill && prefill.repeatWeeks ? prefill.repeatWeeks : null,
          defaultNotes: prefill && prefill.notes ? prefill.notes : "",
          defaultProject: prefill && prefill.project ? prefill.project : null,
          onSubmit: async (result) => {
            if (!result) return;
            const reminder = await this.addReminder({
              text: result.text,
              start: result.start,
              when: result.when,
              repeat: result.repeat || "none",
              repeatInterval: result.repeatInterval || 1,
              repeatDays: result.repeatDays || [],
              repeatWeeks: result.repeatWeeks || null,
              repeatUntil: result.repeatUntil || null,
              recurrenceMode: result.recurrenceMode || "fixed_schedule",
              notes: result.notes || "",
              project: result.project || null
            });
            if (result.calendarStart && result.calendarEnd) {
              let plane = null;
              if (result.project) {
                const projectFile = resolveProjectFile(this.app, result.project);
                if (projectFile) {
                  try {
                    plane = trelloPlaneForProject(readEntity(this.app, projectFile), projectNameFromPath(this.app, projectFile.path) || projectFile.basename);
                  } catch (_) {
                  }
                }
              }
              await createCadenceEvent(this.app, {
                title: `Work on ${result.text}`,
                eventType: "work-block",
                notes: result.notes || null,
                start: result.calendarStart,
                end: result.calendarEnd,
                plane,
                project: result.project || null,
                linkedKind: "reminder",
                linkedId: reminder.id,
                linkedTitle: reminder.text,
                repeat: "none",
                status: "scheduled"
              });
              new obsidian.Notice(`Task saved \xB7 scheduled ${reminderTimeStr(result.calendarStart)}-${reminderTimeStr(result.calendarEnd)}${result.when ? ` \xB7 due ${reminderTimeStr(result.when)}` : ""}`);
            } else if (result.when) {
              new obsidian.Notice(`Task saved \xB7 due ${reminderTimeStr(result.when)}`);
            } else {
              new obsidian.Notice("Captured to Inbox");
            }
          }
        }).open();
      }
